#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MIN(a,b) ((a) < (b) ? (a) : (b))

#define MAX_SIZE 100

int cmp1(const void* a, const void* b) {
    int A;
    sscanf(*(char**) a, "%d", &A);

    int B;
    sscanf(*(char**) b, "%d", &B);

    return A - B;
}

int cmp2(const void* a, const void* b) {
    char* A = *((char**) a);
    char* B = *((char**) b);

    char AB[10000] = {'\0'};
    strcat(AB, A);
    strcat(AB, B);

    char BA[10000] = {'\0'};
    strcat(BA, B);
    strcat(BA, A);

    return strcmp(AB, BA);
}

int main() {
    char line[10000];
    gets(line);

    char* ss[MAX_SIZE];
    int ss_size = 0;

    char* token = strtok(line, ",");
    while(token != NULL) {
        ss[ss_size++] = token;
        token = strtok(NULL, ",");
    }

    qsort(ss, ss_size, sizeof(char*), cmp1);

    int size = MIN(3, ss_size);
    qsort(ss, size, sizeof(char*), cmp2);

    char res[10000];
    for(int i=0; i<size; i++) {
        strcat(res, ss[i]);
    }

    puts(res);

    return 0;
}
